-- ==============================================================================
-- CLEAN IMPORT SQL SCRIPT FOR PROJECTS AND MAPPED PLOTS
-- Generated from Cloned Database Export
-- Run this script in your target Supabase project's SQL Editor
-- ==============================================================================

SET search_path = public;

-- 1. IMPORT PROJECTS
ON CONFLICT (code) DO UPDATE SET 
  name=EXCLUDED.name, 
  location=EXCLUDED.location, 
  description=EXCLUDED.description, 
  cover_image_url=EXCLUDED.cover_image_url, 
  layout_image_url=EXCLUDED.layout_image_url,
  status=EXCLUDED.status;

-- 2. IMPORT MAPPED PLOTS & BOUNDARIES
ON CONFLICT (project_id, plot_number) DO UPDATE SET 
  price=EXCLUDED.price, 
  area_sqft=EXCLUDED.area_sqft, 
  polygon_coordinates=EXCLUDED.polygon_coordinates, 
  layout_x=EXCLUDED.layout_x, 
  layout_y=EXCLUDED.layout_y, 
  status=EXCLUDED.status;
