INSERT INTO public.projects (id, code, name, location, description, google_maps_link, cover_image_url, layout_image_url, launch_date, status, created_at, updated_at) 
VALUES 
  ('3d04f5f1-acbb-423c-8bfd-7faeae964748'::uuid, 'The Urban Subrubs', 'Future City', 'North District', 'Urban and suburban lands represent two distinct types of human settlements. Urban areas feature high population density, skyscrapers, and extensive commercial zones. In contrast, suburban areas sit just outside city centers and are predominantly residential.', NULL, 'https://zolbuckwnjsxfgqqkcjj.supabase.co/storage/v1/object/public/project-layouts/covers/1785483623000-gov.1.png', '3d04f5f1-acbb-423c-8bfd-7faeae964748/layout-1785483604673.png', NULL::date, 'upcoming'::public.project_status, '2026-07-22 12:07:18.665782+00'::timestamptz, '2026-07-31 07:40:29.800212+00'::timestamptz),
  ('4c90fac9-c5e3-4788-86a0-e898989394b0'::uuid, 'HAEGL ', 'HAEGL Properties', 'Hubli', 'HAEGL was founded in 2018, committed to the development and implantation of hospital agriculture and education technology. HAEGL has enabled healthcare delivery organizations achieve safer and more efficient patient care, reduced length of stay, while simultaneously ensuring improved revenue cycle management.', NULL, 'https://zolbuckwnjsxfgqqkcjj.supabase.co/storage/v1/object/public/project-layouts/covers/1785481979962-haegl%20properties.png', '4c90fac9-c5e3-4788-86a0-e898989394b0/layout-1785483691890.png', NULL::date, 'upcoming'::public.project_status, '2026-07-21 08:41:26.911322+00'::timestamptz, '2026-07-31 07:41:37.099251+00'::timestamptz),
  ('5b9d6b29-7752-4a64-b1e4-88c70b01b932'::uuid, 'GOT01', 'Winterfell', 'Westeros', 'Winterfell is the ancestral castle and seat of power of House Stark and is considered to be the capital of the north. It is in the center of the northernmost province of the Seven Kingdoms', NULL, 'https://zolbuckwnjsxfgqqkcjj.supabase.co/storage/v1/object/public/project-layouts/covers/1785484004500-wtf.png', '5b9d6b29-7752-4a64-b1e4-88c70b01b932/layout-1784179819165.png', NULL::date, 'live'::public.project_status, '2026-07-16 05:22:36.523852+00'::timestamptz, '2026-07-31 07:46:53.695058+00'::timestamptz),
  ('d1a15161-0d96-4a74-8d19-8d420893a95b'::uuid, 'P001', 'Royal Villa Properties', 'RCB', 'Lorem ipsum dolor sit amet consectetur adipisicing elit. Adipisci doloribus quis aut ipsa incidunt voluptate. Impedit perferendis ut doloribus, vitae natus obcaecati accusamus modi animi eaque. Doloremque ex unde eum recusandae, vitae minima voluptatum consectetur sapiente harum, eius eligendi consequuntur.', NULL, 'https://zolbuckwnjsxfgqqkcjj.supabase.co/storage/v1/object/public/project-layouts/covers/1785484285133-rvp.png', 'd1a15161-0d96-4a74-8d19-8d420893a95b/layout-1784113385951.png', NULL::date, 'live'::public.project_status, '2026-07-15 10:59:52.333634+00'::timestamptz, '2026-07-31 07:51:59.446667+00'::timestamptz),
  ('27435209-22bb-4894-8ec8-8852e4d0a8d6'::uuid, 'UX003', 'Unique Valley', 'Keshwapur', 'sdfdsf', NULL, 'https://zolbuckwnjsxfgqqkcjj.supabase.co/storage/v1/object/public/project-layouts/covers/1786511974765-482316678_3934767876812848_1438853118651003878_n.jpg', '27435209-22bb-4894-8ec8-8852e4d0a8d6/layout-1786511984354.jpg', NULL::date, 'archived'::public.project_status, '2026-08-12 05:16:27.642406+00'::timestamptz, '2026-08-12 05:19:46.005285+00'::timestamptz)
